import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

max_pool1d_source = r"""
#include <cfloat>
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void max_pool1d_kernel(
    const float* input,
    float* output,
    int batch,
    int channels,
    int in_length,
    int out_length,
    int kernel_size,
    int stride,
    int padding,
    int dilation)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch * channels * out_length) return;

    int out_idx = idx % out_length;
    int channel_idx = (idx / out_length) % channels;
    int batch_idx = idx / (out_length * channels);

    int start = out_idx * stride - padding;
    float max_val = -FLT_MAX;

    for (int k = 0; k < kernel_size; k++) {
        int in_idx = start + k * dilation;
        if (in_idx >= 0 && in_idx < in_length) {
            float val = input[batch_idx * channels * in_length + channel_idx * in_length + in_idx];
            max_val = max(max_val, val);
        }
    }

    output[batch_idx * channels * out_length + channel_idx * out_length + out_idx] = max_val;
}

torch::Tensor max_pool1d_cuda(
    torch::Tensor input,
    int kernel_size,
    int stride,
    int padding,
    int dilation)
{
    auto batch = input.size(0);
    auto channels = input.size(1);
    auto in_length = input.size(2);

    int out_length = (int)((in_length + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1);
    auto options = torch::TensorOptions().dtype(input.dtype()).device(input.device());
    auto output = torch::empty({batch, channels, out_length}, options);

    int total = batch * channels * out_length;
    int block_size = 256;
    int grid_size = (total + block_size - 1) / block_size;

    max_pool1d_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch,
        channels,
        in_length,
        out_length,
        kernel_size,
        stride,
        padding,
        dilation
    );

    return output;
}
"""

max_pool1d_cpp_source = r"""
torch::Tensor max_pool1d_cuda(
    torch::Tensor input,
    int kernel_size,
    int stride,
    int padding,
    int dilation);
"""

max_pool1d = load_inline(
    name="max_pool1d_op",
    cpp_sources=max_pool1d_cpp_source,
    cuda_sources=max_pool1d_source,
    functions=["max_pool1d_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, kernel_size: int, stride: int = None, padding: int = 0, dilation: int = 1, return_indices: bool = False):
        super().__init__()
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size
        self.padding = padding
        self.dilation = dilation
        self.return_indices = return_indices

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return max_pool1d.max_pool1d_cuda(
            x,
            self.kernel_size,
            self.stride,
            self.padding,
            self.dilation
        )
